"""Original, topic-specific advanced lessons. Code/logs are instructional fragments.
Each topic has four mechanism steps, code blocks, failure observations, diagnostics,
and four explained questions. Nothing in these examples is executed by the site.
"""
COURSES=[]
def add(id,title,goal,problem,scope,mechanism,code,failure,observe,qa,refs,language='Kotlin'):
    assert all(len(v)==4 for v in (mechanism,code,failure,observe,qa)),id
    COURSES.append(dict(id=id,title=title,goal=goal,problem=problem,scope=scope,mechanism=mechanism,code=code,failure=failure,observe=observe,qa=qa,refs=refs,language=language))
